patches.after:
.content-day__fresh-head .app-btn{width:auto;flex:0 0 auto}
/* 03.11.2026: ПК — обычные размеры кнопок и карточек, экран используется по ширине. Телефон не меняется. */
@media(min-width:1024px){
 .app-body[data-layout="dashboard"]{grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:12px}
 .app-body[data-layout="dashboard"]>.app-btn{min-height:60px;padding:12px 18px;border-radius:12px;font-size:.95rem}
 .app-body>.app-btn{min-width:0;min-height:38px;padding:8px 18px;font-size:.92rem}
 .app-sidebar .app-menu__item{min-height:38px;padding:8px 12px}
 .app-btn{min-height:38px;padding:8px 16px;font-size:.92rem}
 .content-tasks-dialog{padding:24px}
 .content-tasks-dialog__surface{width:min(100%,1280px);height:100%;border-radius:16px;overflow:hidden;box-shadow:0 18px 48px #1d1c1633}
 .content-tasks-dialog__body{padding:20px 24px}
 .content-tasks-dialog .app-btn{min-height:36px;padding:7px 16px;font-size:.9rem}
 .content-day__create,.content-day>div>.content-day__create{min-width:0;padding-inline:20px}
 .content-day__all{justify-self:start;width:auto}
 .content-day__channel-head .app-btn{width:auto}
 .palitra-composer-primary,.palitra-composer-secondary,.palitra-composer-danger{min-height:38px;padding:8px 18px;font-size:14px}
 .palitra-composer-input{min-height:38px;padding-top:7px;padding-bottom:7px;font-size:15px}
 .palitra-composer-input:is(select){min-height:38px}
 .palitra-composer-close{min-width:36px;min-height:36px}
}
